import UIKit

@main
class AppDelegate: UIResponder, UIApplicationDelegate {
    var window: UIWindow?

    func application(_ application: UIApplication, didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
        window = UIWindow(frame: UIScreen.main.bounds)
        window?.rootViewController = UIViewController()
        window?.makeKeyAndVisible()
        return true
    }
}

import XCTest

final class LongPressTests: XCTestCase {
    func testLongPressBookClub() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        let cell = app.cells.containing(.staticText, identifier: "Book Club").firstMatch
        if cell.waitForExistence(timeout: 20) {
            cell.press(forDuration: 1.0)
        } else {
            let text = app.staticTexts["Book Club"].firstMatch
            XCTAssertTrue(text.waitForExistence(timeout: 20), "Book Club element not found")
            text.press(forDuration: 1.0)
        }
        Thread.sleep(forTimeInterval: 3.0)
    }
}

